window.kbPageData["views/entry/k-47a0525895bf8c94"] = {"key":"entry/k-47a0525895bf8c94","state":{"route":"entry/k-47a0525895bf8c94"},"node":{"id":"k-47a0525895bf8c94","mode":"k","title":"德摩根律（析取的否定）","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["析取命题的否定等价于各析取支否定的合取","德摩根律：相容析取的否定等价于各析取支的否定的合取"],"qs":["江苏 2024 A类 行测#98","江苏 2024 B类 行测#98"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"否定“至少一项成立”等价于断定“两项都不成立”，即“甲或乙”的否定是“非甲且非乙”。","review":{"definition":"否定“至少一项成立”等价于断定“两项都不成立”，即“甲或乙”的否定是“非甲且非乙”。","explanation":"研发部录用硕士生后，第③条预测的后件“研发部录用本科生”不成立，因而前件“财务部录用本科生或者硕士生”整体不成立。用德摩根律可分别排除财务部录用本科生和录用硕士生两种情形。三种候选学历中只剩博士生，因此D项不符合预测。","references":[],"evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","disposition":"独立词条","basis":"据原题和解析编释。","title":"德摩根律（析取的否定）","related":[],"examFocus":{"江苏 2024 A类 行测#98":"把有关研发部和财务部的预测写成条件命题，再用逆否推理和德摩根律检验录用情形是否相容。","江苏 2024 B类 行测#98":"把有关研发部和财务部的预测写成条件命题，再用逆否推理和德摩根律检验录用情形是否相容。"}},"readings":[{"origin":"k-47a0525895bf8c94","title":"德摩根律（析取的否定）","qs":["江苏 2024 A类 行测#98"],"definition":"否定“至少一项成立”等价于断定“两项都不成立”，即“甲或乙”的否定是“非甲且非乙”。","explanation":"研发部录用硕士生后，第③条预测的后件“研发部录用本科生”不成立，因而前件“财务部录用本科生或者硕士生”整体不成立。用德摩根律可分别排除财务部录用本科生和录用硕士生两种情形。三种候选学历中只剩博士生，因此D项不符合预测。","evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","doubt":"","references":[]},{"origin":"k-cd3e25385056c388","title":"德摩根律（析取的否定）","qs":["江苏 2024 B类 行测#98"],"definition":"否定“A或B”等价于“非A且非B”。只要有一个分命题成立，相容析取就成立，因此否定整个析取必须否定每个分命题。","explanation":"研发部只录用一人，录用硕士生就排除了录用本科生。由预测（3）的后件不成立，可推出前件“财务部录用本科生或者硕士生”不成立。把这个析取的否定展开，可同时排除财务部录用本科生和硕士生。材料只给出三类学历，因此财务部只能录用博士生，D项不符合预测。","evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#98":{"paper":"江苏 2024 A类 行测","n":98,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",20],"asrc":["0126a1c8aceee632ea2b.pdf",30],"card":"82037a0a76770f3bd03e93b1","links":[{"id":"k-47a0525895bf8c94","role":"解题依据","why":"否定含“或者”的前件后，可以分别排除其中的两种学历。"}]},"江苏 2024 B类 行测#98":{"paper":"江苏 2024 B类 行测","n":98,"mod":"判断推理","src":["0ae7ac475476e5635bd7.pdf",19],"asrc":["8dd171daee6fc74e9718.pdf",33],"card":"5f6b9c7fb6f7aebc47356b8b","links":[{"id":"k-47a0525895bf8c94","role":"解题依据","why":"财务部录用本科生或硕士生这一前件为假，意味着两种情形都被排除。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-47a0525895bf8c94":[["江苏 2024 A类 行测#98"],["江苏 2024 B类 行测#98"]]}};
